pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint104 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // Deploy adversarial callee that always fails on receiving Ether
        Reverter reverter = new Reverter();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        // Withdraw from the actor, sending to the reverter, which will fail
        vm.prank(actor);
        c.withdrawAll();
        // Re-deposit by actor, routing through reverter again (this time to reverter)
        // The property: total deposited minus total successfully withdrawn equals contract balance.
        // After a failed withdrawAll via reverter, contract balance should still equal total credit.
        uint256 totalCredit;
        // We only have one depositor; we can compute totalCredit by iterating over nothing.
        // Instead, use a getter: credit is public mapping, but we cannot iterate.
        // Since we know actor deposited and credit[actor] was set, we can check:
        // The single assertion: contract balance == credit[actor] for all inputs.
        // The correct version reverts on failed call, so credit[actor] remains amount and balance remains amount.
        // The buggy version zeroes credit and deducts balance, so balance becomes 0 while credit[actor] is 0, but balance is 0 and credit is 0 -> they match?
        // Wait: buggy deducts balance and zeroes credit on failure. Credit becomes 0, balance becomes 0. That's actually equal.
        // We need a different adversarial: actor deposits, then actor withdraws to a contract that fails. Correct reverts (balance unchanged, credit unchanged). Buggy deducts and zeroes.
        // Then we check balance vs credit[actor]. Correct: balance=amount, credit=amount. Buggy: balance=0, credit=0. Both equal. Not a difference.
        // We need total credit across all depositors vs balance. Let's have two depositors: actor deposits, then we deposit from another account (this contract). We force a withdrawal by actor to the reverter, which fails. Then credit[actor] becomes 0 in buggy, but balance deducted. Then sum of credits (credit[actor] + credit[this]) != balance in buggy.
        // Let's do that.
        address depositor2 = address(this);
        uint256 amount2 = 1 ether;
        vm.deal(depositor2, amount2);
        vm.prank(depositor2);
        c.deposit{value: amount2}();
        // Now actor withdraws to reverter
        vm.prank(actor);
        c.withdrawAll();
        // Calculate total credit: credit[actor] + credit[depositor2]
        uint256 totalCreditAfter = c.credit(actor) + c.credit(depositor2);
        uint256 balanceAfter = address(c).balance;
        assertTrue(totalCreditAfter == balanceAfter);
    }
}

