pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address depositor2) public {
        address actor = address(this);
        vm.assume(depositor2 != address(0) && depositor2 != actor && depositor2 != address(c));
        vm.assume(amount1 > 0 && amount2 > 0);

        // Deploy a reverter that will make the low-level call fail
        Reverter reverter = new Reverter();

        // Deposit for the actor
        vm.deal(actor, amount1);
        vm.prank(actor);
        c.deposit{value: amount1}();

        // Deposit for the reverter (adversarial depositor that will fail on receive)
        vm.deal(address(reverter), amount2);
        vm.prank(address(reverter));
        c.deposit{value: amount2}();

        // Record state before withdrawAll by the reverter
        uint256 balanceBefore = address(c).balance;
        uint256 creditReverterBefore = c.credit(address(reverter));
        uint256 creditActorBefore = c.credit(actor);

        // The reverter calls withdrawAll, which will attempt to send value back to itself and fail
        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;
        uint256 creditReverterAfter = c.credit(address(reverter));
        uint256 creditActorAfter = c.credit(actor);

        // General rule: on a failed withdrawAll, the state must be completely unchanged.
        // The bug zeroes credit and deducts balance even when the external call fails.
        assertTrue(
            ok || (
                balanceAfter == balanceBefore &&
                creditReverterAfter == creditReverterBefore &&
                creditActorAfter == creditActorBefore
            )
        );
    }
}

