pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount > 0 && amount <= 1000 ether);
        // deploy a contract that always reverts on receiving ether
        Reverter reverter = new Reverter();
        address actor = address(reverter);
        // deposit some credit for the adversarial actor
        vm.deal(address(this), amount);
        c.deposit{value: amount}();
        // transfer that credit to the reverter contract
        c.withdrawAll();
        // now the reverter has credit, and c has balance equal to its credit
        vm.deal(address(c), 0); // reset c's balance to avoid confusion, but it already holds amount from deposit+withdraw
        // Actually above withdrawAll sent ether to this contract, not to reverter. Let's do it correctly:
        // We need the reverter to have credit. So:
        vm.deal(address(this), amount);
        c.deposit{value: amount}();
        // Now credit[this] = amount. We need credit[reverter] = something. So deposit from reverter?
        // We can't prank reverter because it has no code to call deposit.
        // Instead, we can transfer credit by this contract calling withdrawAll, then reverter somehow getting credit?
        // The fuzzer can fuzz an amount, but the reverter must be the one calling withdrawAll to trigger the bug on itself.
        // So we need to give the reverter credit first. We can do that by this contract depositing on behalf of reverter?
        // No, deposit uses msg.sender. So we can prank reverter and deposit to it. But reverter has no fallback that accepts deposits?
        // Actually deposit is payable and doesn't call reverter. We can do:
        vm.prank(actor);
        c.deposit{value: amount}();
        // That works because deposit does not call actor. Now credit[actor] = amount.
        // Now record state before withdrawAll
        uint256 creditBefore = c.credit(actor);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // The call should fail because actor is a Reverter, but the buggy version doesn't have require(callResult) so it continues and resets credit.
        // Assert: if the call failed, credit must remain unchanged; if succeeded, credit must be 0.
        // But the call always fails? Actually low-level call to Reverter fails, so with require it reverts entire withdrawAll. Without require, it proceeds.
        // So in correct version, ok = false (entire function reverts) and credit unchanged.
        // In buggy version, ok = true (no revert), credit becomes 0.
        uint256 creditAfter = c.credit(actor);
        // General rule: success implies credit zeroed, failure implies credit unchanged.
        // But the bug breaks this: on failure (which always happens for Reverter), credit becomes 0 instead of remaining unchanged.
        assertTrue(ok ? creditAfter == 0 : creditAfter == creditBefore);
    }
}

