pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // Keep amount in a reasonable range; actor is an EOA that will not call into c
        bound(amount, 1, 10 ether);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // Fund c to cover withdrawals
        vm.deal(address(c), amount);
        // Give actor credit via deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // Deploy an adversarial callee that reverts on receiving ETH, so the low-level call in withdrawAll fails
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), 0); // ensure it has no ETH to return
        // Give the reverter credit (pretend it deposited)
        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        c.deposit{value: amount}();

        // Record ETH balance of the adversarial callee before withdrawAll
        uint256 reverterBalanceBefore = address(reverter).balance;

        // Call withdrawAll as the reverter
        bool success;
        vm.prank(address(reverter));
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        // After the call, the following universal rule must hold:
        // If withdrawAll did not revert, then the callee must have received the ether.
        // i.e., success => address(reverter).balance > reverterBalanceBefore
        // The bug zeros credit and deducts balance but does not revert on failed call,
        // so success is true but the reverter did not receive funds.
        assertTrue(!success || address(reverter).balance > reverterBalanceBefore);
    }
}

