pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Reverter {
    fallback() external payable {
        revert();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Bound amount to avoid overflow and keep it positive to trigger the path
        vm.assume(amount > 0 && amount < 1 ether);

        // Deploy the adversarial helper that will revert on receive
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Give actor some initial ETH to be able to deposit (it will send ETH from itself)
        vm.deal(actor, amount);

        // Act as the actor and deposit ETH into C
        vm.prank(actor);
        c.deposit{value: amount}();

        // Record state before withdrawAll
        uint256 creditBefore = c.credit(actor);
        uint256 balanceBefore = address(c).balance;

        // Execute withdrawAll as the actor. The external call will revert, but we
        // check if the whole transaction reverts or not to handle both behaviors.
        bool txReverted;
        vm.prank(actor);
        try c.withdrawAll() {
            txReverted = false;
        } catch {
            txReverted = true;
        }

        // After the attempt, read final state
        uint256 creditAfter = c.credit(actor);
        uint256 balanceAfter = address(c).balance;

        // General rule: if the withdrawAll transaction doesn't revert (the bug allows state
        // mutation despite failed low‑level call), then the actor's credit must be zero and
        // the contract's balance must be balanceBefore - creditBefore.
        // If it reverts, state must be unchanged.
        // The reference C always reverts (due to require(callResult)) when the external call
        // fails, so state remains unchanged. The bug does not revert and mutates state.
        if (!txReverted) {
            assertTrue(creditAfter == 0 && balanceAfter == balanceBefore - creditBefore);
        } else {
            assertTrue(creditAfter == creditBefore && balanceAfter == balanceBefore);
        }
    }
}

