pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(attacker != address(this));
        vm.deal(attacker, amount);
        vm.prank(attacker);
        c.deposit{value: amount}();
        Attacker helper = new Attacker(c);
        vm.deal(address(helper), 0);
        helper.attack();
        assertTrue(address(c).balance == c.balance());
    }
}

contract Attacker {
    C c;
    uint256 count;
    constructor(C _c) { c = _c; }
    function attack() external {
        c.withdrawAll();
    }
    receive() external payable {
        if (count < 1 && address(c).balance >= 1 wei) {
            count++;
            c.withdrawAll();
        }
    }
}
